for(const c in CLS)for(const s of CLS[c].sk){const t=s.dt,v=s.dv;s.d=L=>{const o=v?v(L):{};return t.replace(/\{(\w+)\}/g,(m,k)=>k in o?o[k]:m)}}
/* SKN.scrapper[0].dmg(L): a skill's formulas by class and tree position, for the casting code. */
const SKN={};for(const c in CLS)SKN[c]=CLS[c].sk.map(s=>s.f);
if (typeof module !== 'undefined' && module.exports) module.exports = { CLS, SKN };
